import os,subprocess
from pathlib import Path
w=Path(Path('/tmp/my-llm-parameter-perf-path').read_text());root=Path.cwd();python=str(root/'.venv/bin/python')
def run(label,name,args):
 env={**os.environ,'PYTHONPATH':str(w/label/'src')+os.pathsep+str(root)}
 print(name,flush=True)
 with (w/(name+'.log')).open('w') as log:subprocess.run([python,*args],env=env,stdout=log,stderr=subprocess.STDOUT,check=True)
for i,label in enumerate(['current','dedup','lazy_event','lazy_event','dedup','current'],1):
 name=f'event-{i}-{label}';run(label,name,['/tmp/my_llm_parameter_event_micro.py',str(w/(name+'.json'))])
run('current','gc',['-m','tests.performance.gc_diagnostic',str(w/'gc.json'),'--protocol','openai_responses','--iterations','41','--warmup','5'])
for label in ['dedup','cached_fields','lazy_event']:
 run(label,label+'-tests',['-m','pytest','-q','tests/unit/test_output_parameter_events.py','tests/unit/test_parameter_identity.py','tests/unit/test_profile_declarations.py','tests/unit/test_profile_members.py','tests/integration/test_sdk_transport.py','--tb=short'])
for i,label in enumerate(['current','before','before','current'],1):
 name=f'cross-repeat-{i}-{label}'
 run(label,name,['-m','tests.performance','--suite','cross','--upstream','ollama','--stdio','openai_chat','--iterations','31','--warmup','5','--json',str(w/(name+'.json'))])
print('Followups complete',flush=True)
